def apply_world_record_mastery_baseline(records: list[dict]) -> bool:
    global TRACK_THRESHOLDS
    if len(records) != 192:
        return False
    by_key = {(row.get("mode"), row.get("trackId")): row.get("totalTimeMs") for row in records if isinstance(row, dict)}
    if len(by_key) != 192 or any(not isinstance(value, int) or value <= 0 for value in by_key.values()):
        return False
    updated = {}
    for track_id in TRACK_THRESHOLDS:
        updated[track_id] = {}
        for mode in (150, 200):
            wr = by_key.get((mode, track_id))
            if wr is None:
                return False
            updated[track_id][str(mode)] = [int(wr * ratio / 100 + 0.5) * 100 for ratio in MASTERY_WR_RATIOS] + [600000]
    TRACK_THRESHOLDS = updated
    return True

def track_mastery_tier(track_id: str, mode: int, time_ms: int):
    rows = TRACK_THRESHOLDS.get(track_id)
    if rows is None or str(mode) not in rows:
        return None
    for index, limit in enumerate(rows[str(mode)]):
        if time_ms <= limit:
            return index
    return len(rows[str(mode)]) - 1

def track_mastery_label(track_id: str, mode: int, time_ms: int):
    tier = track_mastery_tier(track_id, mode, time_ms)
    return None if tier is None else TIER_LABELS[tier]

def track_mastery_ladder(track_id: str, mode: int):
    rows = TRACK_THRESHOLDS.get(track_id)
    return None if rows is None else rows.get(str(mode))
